import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Approvals & Resume Tokens","description":"","frontmatter":{},"headers":[],"relativePath":"guide/approvals.md","filePath":"guide/approvals.md","lastUpdated":1792243762000}'),p={name:"guide/approvals.md"};function l(t,s,r,c,i,d){return a(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="approvals-resume-tokens" tabindex="-1">Approvals &amp; Resume Tokens <a class="header-anchor" href="#approvals-resume-tokens" aria-label="Permalink to &quot;Approvals &amp; Resume Tokens&quot;">​</a></h1><p>A tool call can wait for a human. The run pauses in <code>waiting</code>, the owner gets a notification with a signed resume token, and <code>engine.resume(token, decision)</code> continues the run, minutes or days later, on any replica.</p><h2 id="declaring-approvals" tabindex="-1">Declaring approvals <a class="header-anchor" href="#declaring-approvals" aria-label="Permalink to &quot;Declaring approvals&quot;">​</a></h2><p><code>approvals</code> maps tool names to a policy. <code>&#39;user&#39;</code> always asks. A function decides per call and returns <code>&#39;user&#39;</code> (ask), <code>&#39;allow&#39;</code> (run without asking) or <code>&#39;deny&#39;</code> (refuse without asking). It receives the tool input and <code>{ runtimeContext }</code>, the run context.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> deployer = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;deployer&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Deploy the requested version.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> ({</span></span>
<span class="line"><span style="color:#E6DFDE;">        deploy: tool({</span></span>
<span class="line"><span style="color:#E6DFDE;">            description: </span><span style="color:#E7C58C;">&#39;Deploys a version to an environment.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            inputSchema: z.object({ version: z.string(), env: z.enum([</span><span style="color:#E7C58C;">&#39;staging&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&#39;prod&#39;</span><span style="color:#E6DFDE;">]) }),</span></span>
<span class="line"><span style="color:#E6DFDE;">            execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ version, env }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> deployVersion(version, env),</span></span>
<span class="line"><span style="color:#E6DFDE;">        }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    approvals: {</span></span>
<span class="line"><span style="color:#958A8B;">        // staging deploys run right away, prod deploys wait for the owner</span></span>
<span class="line"><span style="color:#E6DFDE;">        deploy: (input) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> ((input </span><span style="color:#FF7B84;">as</span><span style="color:#E6DFDE;"> { env: string }).env === </span><span style="color:#E7C58C;">&#39;prod&#39;</span><span style="color:#E6DFDE;"> ? </span><span style="color:#E7C58C;">&#39;user&#39;</span><span style="color:#E6DFDE;"> : </span><span style="color:#E7C58C;">&#39;allow&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">    approvalTimeoutMs: </span><span style="color:#E7C58C;">60</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">1000</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    notify: </span><span style="color:#E7C58C;">&#39;owner&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The engine translates the policies into the AI SDK&#39;s <code>toolApproval</code> and signs the approval requests with <code>resumeSecret</code>.</p><h2 id="the-pause" tabindex="-1">The pause <a class="header-anchor" href="#the-pause" aria-label="Permalink to &quot;The pause&quot;">​</a></h2><p>When a step asks for an approval:</p><ol><li>The first unanswered approval request becomes the run&#39;s <strong>wait point</strong> (<code>run.waiting</code>): <code>approvalId</code>, <code>toolName</code>, <code>input</code>, <code>expiresAt</code> and a <code>tokenId</code>.</li><li>The run moves <code>running</code> to <code>waiting</code> and releases its claim and its slot. A run with a concurrency key keeps the key blocked while it waits.</li><li>The agent&#39;s notifier (<code>notify</code>) gets one <code>approval</code> notification with the resume token. A successful send records <code>waiting.notifiedAt</code>.</li></ol><p>One approval per pause: when one step asks for several approvals, the run waits on the first and the other calls are dropped from the history. The model asks for them again after the resume if it still needs them.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> resumeSecret = process.env.RESUME_SECRET;</span></span>
<span class="line"><span style="color:#FF7B84;">if</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">!</span><span style="color:#E6DFDE;">resumeSecret) </span><span style="color:#FF7B84;">throw</span><span style="color:#FF7B84;"> new</span><span style="color:#E6DFDE;"> Error(</span><span style="color:#E7C58C;">&#39;RESUME_SECRET is not set&#39;</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> inbox = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> InboxNotifier();</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> RunEngine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store: </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> MemoryStore(),</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [deployer],</span></span>
<span class="line"><span style="color:#E6DFDE;">    notifiers: { owner: inbox },</span></span>
<span class="line"><span style="color:#E6DFDE;">    resumeSecret,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The engine throws <code>InvalidAgentDefinitionError</code> for an empty <code>resumeSecret</code> (anyone could mint tokens with it) and for a <code>notify</code> that names no registered notifier.</p><h2 id="resuming" tabindex="-1">Resuming <a class="header-anchor" href="#resuming" aria-label="Permalink to &quot;Resuming&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> run = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.getRun(runId);</span></span>
<span class="line"><span style="color:#FF7B84;">if</span><span style="color:#E6DFDE;"> (run?.status === RunStatus.WAITING </span><span style="color:#FF7B84;">&amp;&amp;</span><span style="color:#E6DFDE;"> run.waiting) {</span></span>
<span class="line"><span style="color:#FF7B84;">    const</span><span style="color:#E6DFDE;"> token = inbox.tokens.get(</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">run</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">id</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">:</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">run</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">waiting</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">approvalId</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#FF7B84;">    if</span><span style="color:#E6DFDE;"> (token) {</span></span>
<span class="line"><span style="color:#FF7B84;">        await</span><span style="color:#E6DFDE;"> engine.resume(token, { approved: </span><span style="color:#FF7B84;">false</span><span style="color:#E6DFDE;">, reason: </span><span style="color:#E7C58C;">&#39;Not on a Friday.&#39;</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#E6DFDE;">    }</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span></code></pre></div><p><code>resume()</code> verifies the token against the run&#39;s current wait point, moves the run <code>waiting</code> to <code>queued</code>, appends the <code>tool-approval-response</code> to the checkpoint and a <code>wait</code> step, and clears the wait point. The next execution runs the approved call, or tells the model it was denied (with your <code>reason</code>).</p><ul><li>A token answers its wait point once. A second <code>resume()</code> throws <code>InvalidRunStateError</code>.</li><li>A forged, malformed, expired or superseded token throws <code>InvalidResumeTokenError</code>.</li><li>If writing the answer fails, the run goes back to <code>waiting</code> and the token stays valid.</li></ul><h2 id="timeouts" tabindex="-1">Timeouts <a class="header-anchor" href="#timeouts" aria-label="Permalink to &quot;Timeouts&quot;">​</a></h2><p>An approval not answered within <code>approvalTimeoutMs</code> (default 24 hours) is denied with the reason <code>approval timed out</code>. The engine checks on every poll (<code>tick()</code>). The model sees the denial and can react.</p><h2 id="notification-retries" tabindex="-1">Notification retries <a class="header-anchor" href="#notification-retries" aria-label="Permalink to &quot;Notification retries&quot;">​</a></h2><p>A failed send is retried on every poll until it succeeds. A store lock per approval keeps replicas from sending at the same time, and the notifier receives a stable <code>idempotencyKey</code> (<code>&lt;runId&gt;:&lt;approvalId&gt;</code>) to drop a duplicate whose delivery record was lost. See <a href="/guide/notifiers">Notifiers</a>.</p><h2 id="token-format" tabindex="-1">Token format <a class="header-anchor" href="#token-format" aria-label="Permalink to &quot;Token format&quot;">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span>base64url(JSON { runId, approvalId, tokenId, exp }) + &quot;.&quot; + base64url(HMAC-SHA256(resumeSecret, payload))</span></span></code></pre></div><p>The signature is compared in constant time, and a token expires at the wait point&#39;s <code>expiresAt</code>. <code>createResumeToken(secret, claims)</code> and <code>verifyResumeToken(secret, token, now)</code> are exported for transports that carry tokens themselves.</p><div class="tip custom-block"><p class="custom-block-title">Where tokens are answered</p><p>In core you call <code>engine.resume()</code> yourself. The planned <a href="/roadmap#planned-packages"><code>@chamberu/http</code></a> package adds an authenticated resume endpoint and an MCP <code>resume_run</code> tool, and the planned UI an approvals inbox.</p></div>`,24)])])}const u=e(p,[["render",l]]);export{y as __pageData,u as default};
